// v1.2.182: логотипы мессенджеров как data-URI (встроены строкой — не зависят от сборки,
// работают и в разработке, и в упакованном приложении; CSP index.html разрешает img-src data:).
// Только у кого есть логотип-картинка; у остальных значок берётся из эмодзи (messengerBranding.js).
// Telegram: 128x128 RGBA, ~7 КБ (из PNG/T1.png).
import { detectMessengerType } from '../../utils/messengerConfigs.js' // v1.2.379: логотип уведомления по типу из url (не по id)
export const MESSENGER_LOGOS = {
  // Ozon: 256x256 RGBA (из PNG/Ozon.png).
  ozon: 'data:image/png;base64,',
  telegram: 'data:image/png;base64,',
  // WhatsApp: 128x128 RGBA (из PNG/whatsapp-icon.png). Реальный логотип вместо эмодзи 💬 (v1.2.314).
  whatsapp: 'data:image/png;base64,',
  // ВКонтакте: 129x129 RGBA (из PNG/VK-icon.png). Реальный логотип вместо эмодзи 🔵 (v1.2.315).
  vk: 'data:image/png;base64,',
  // МАКС: 129x129 RGBA (из PNG/max-icon.png). Реальный логотип вместо эмодзи 💎 (v1.2.316).
  max: 'data:image/png;base64,',
}

// messenger → data-URI логотипа или null (тогда caller показывает эмодзи).
export function getMessengerLogo(messenger) {
  return MESSENGER_LOGOS[messenger] || null
}

// v1.2.379: логотип для УВЕДОМЛЕНИЯ по объекту мессенджера. Ключи логотипов — ТИПЫ (ozon/telegram/…),
// а id ручного источника = custom_<время> (App.jsx addMessenger) → искать по id нельзя. Определяем тип
// из url, запасной ключ — id (дефолтные, где id=тип), иначе undefined (окно уведомления рисует эмодзи).
// Единый источник для webviewHandleNewMessage (сообщение + авто-ответ), чтобы поиск по id не «вернулся» тихо.
export function resolveMessengerLogo(mInfo) {
  return getMessengerLogo(detectMessengerType(mInfo?.url || '')) || getMessengerLogo(mInfo?.id) || undefined
}
